    "confidence": 0.35,
    "rationale": "ZYG11B evidence includes a detailed table showing impaired receptive language, motor developmental delay, muscular hypotonia, gait abnormalities, and SGA-compatible features, best matching the full HPO profile."
  },
  {
    "gene": "DNMT3A",
    "confidence": 0.12,
    "rationale": "DNMT3A evidence describes infantile hypotonia, delayed walking, moderate ID, poor speech, and cortical malformation-associated gliosis, covering several key HPO terms."
  },
  {
    "gene": "TLCD2",
    "confidence": 0.07,
    "rationale": "Evidence includes MSL3-related disorder description with hypotonia, movement disorders, moderate ID, and delayed ambulation, partially matching the phenotype profile."
  },
  {
    "gene": "RRAS2",
    "confidence": 0.06,
    "rationale": "Evidence covers moderate ID, hypotonia, movement disorders, and developmental delay but lacks specificity for gliosis or SGA."
  },
  {
    "gene": "GTF2E2",
    "confidence": 0.06,
    "rationale": "Evidence includes hypotonia, movement disorders, moderate ID, and delayed walking from MSL3-related disorder description, partially matching HPO terms."
  },
  {
    "gene": "XKR9",
    "confidence": 0.05,
    "rationale": "Evidence covers moderate-severe ID, motor and language delay, and movement abnormalities but lacks direct gene-specific association with gliosis or SGA."
  },
  {
    "gene": "NIPA2",
    "confidence": 0.05,
    "rationale": "Evidence shows hypotonia, delayed walking, language delay, and moderate ID but evidence is non-specific and lacks gliosis or SGA linkage."
  },
  {
    "gene": "SLC5A8",
    "confidence": 0.05,
    "rationale": "Evidence includes SGA (birth weight <3rd percentile), delayed walking, language delay, and ID, but evidence is non-specific to SLC5A8 function."
  },
  {
    "gene": "PRMT3",
    "confidence": 0.04,
    "rationale": "Evidence shows moderate ID and language delay but is non-specific and lacks direct PRMT3-phenotype linkage for gliosis, hypotonia, or SGA."
  },
  {
    "gene": "KRTAP1-5",
    "confidence": 0.04,
    "rationale": "Evidence covers moderate-severe ID, motor and language delay, and hypotonia but KRTAP1-5 is a keratin-associated protein gene with no known neurological disease link."
  },
  {
    "gene": "H1-1",
    "confidence": 0.03,
    "rationale": "Evidence shows hypotonia, delayed walking, and moderate ID but H1-1 is a histone gene with limited direct neurological disease evidence."
  },
  {
    "gene": "CBLB",
    "confidence": 0.03,
    "rationale": "Evidence shows only mild developmental delays and no intellectual disability; poor match for moderate ID, gliosis, and SGA in this patient."
  },
  {
    "gene": "TOMM40",
    "confidence": 0.03,
    "rationale": "Evidence shows mild developmental delays without intellectual disability; TOMM40 is primarily associated with Alzheimer's risk, not pediatric neurodevelopmental disease."
  },
  {
    "gene": "CYP4F3",
    "confidence": 0.02,
    "rationale": "CYP4F3 is a cytochrome P450 enzyme with no established link to neurodevelopmental phenotypes; evidence is entirely non-specific."
  },
  {
    "gene": "CSN2",
    "confidence": 0.02,
    "rationale": "CSN2 encodes milk beta-casein with no known neurological disease association; evidence is entirely non-specific to this gene."
  }
